// CoverLetterClassic (epic-job-applications, slice 2) — a cover-letter SKELETON that pairs with
// ResumeClassic: the same header rule, type and accent, laid out as a business letter from a
// `CoverLetterDoc`. It holds no personal data; given no `doc` it shows the fictional DEMO_COVER_LETTER.
//
// Semantic, single-column and real text throughout, for the same reason as the résumé: what a reader
// extracts from the PDF must read in the order the page does. `page` picks US Letter or A4.
import type { CSSProperties } from "react";
import { DEMO_COVER_LETTER, paperCss, type CoverLetterDoc, type PaperSize } from "@/features/jobs/lib/documents";

const SHEET = "bsc-doc-cover-letter-classic";
const ACCENT = "var(--doc-accent, #1f3a5f)";
const MUTED = "#4a4a4a";

const CSS = `
.${SHEET} { font-family: "Inter", "Helvetica Neue", Arial, sans-serif; font-size: 11pt; line-height: 1.5; }
.${SHEET} h1, .${SHEET} p, .${SHEET} address { margin: 0; font-style: normal; }
.${SHEET} .para { margin: 0 0 9pt; break-inside: avoid; }
`;

const s = {
  header: { borderBottom: `1.5pt solid ${ACCENT}`, paddingBottom: "8pt", marginBottom: "18pt" },
  name: { fontSize: "20pt", fontWeight: 700, color: "#111" },
  headline: { fontSize: "10.5pt", color: MUTED, marginTop: "2pt" },
  contact: { fontSize: "9.5pt", color: MUTED, marginTop: "4pt" },
  date: { marginBottom: "14pt" },
  recipient: { marginBottom: "14pt" },
  greeting: { marginBottom: "10pt" },
  closing: { marginTop: "14pt" },
  signature: { marginTop: "26pt", fontWeight: 600, color: "#111" },
} satisfies Record<string, CSSProperties>;

export function CoverLetterClassic({ doc = DEMO_COVER_LETTER, page = "letter" }: { doc?: CoverLetterDoc; page?: PaperSize }) {
  const h = doc.header;
  const contact = [h.location, h.email, h.phone, ...(h.links ?? [])].filter((x): x is string => !!x && !!x.trim());
  const r = doc.recipient;
  const recipientLines = r ? [r.name, r.title, r.company, ...(r.address ?? [])].filter((x): x is string => !!x && !!x.trim()) : [];
  return (
    <article className={SHEET} data-paper={page} data-document="cover-letter">
      <style>{`${paperCss(page, SHEET)}\n${CSS}`}</style>
      <header style={s.header}>
        <h1 style={s.name}>{h.name}</h1>
        {h.headline && <p style={s.headline}>{h.headline}</p>}
        {contact.length > 0 && <p style={s.contact}>{contact.join("  ·  ")}</p>}
      </header>
      {doc.date && <p style={s.date}>{doc.date}</p>}
      {recipientLines.length > 0 && (
        <address style={s.recipient}>
          {recipientLines.map((line, i) => <p key={i}>{line}</p>)}
        </address>
      )}
      <p style={s.greeting}>{doc.greeting}</p>
      {doc.paragraphs.map((p, i) => (
        <p key={i} className="para" data-sources={p.sources?.join(" ")}>{p.text}</p>
      ))}
      <p style={s.closing}>{doc.closing}</p>
      <p style={s.signature}>{doc.signature ?? h.name}</p>
    </article>
  );
}

export default CoverLetterClassic;

