// CoverLetterClassic (epic-job-applications, slice 2) — a business letter from the content alone, in
// reading order, on the paper asked for.
import { describe, it, expect } from "vitest";
import { render, screen } from "@testing-library/react";
import { CoverLetterClassic } from "@/features/jobs/CoverLetterClassic";
import { DEMO_COVER_LETTER, type CoverLetterDoc } from "@/features/jobs/lib/documents";

describe("CoverLetterClassic", () => {
  it("renders the demo letter when given no content, in letter order", () => {
    const { container } = render(<CoverLetterClassic />);
    const text = container.textContent ?? "";
    const order = [
      DEMO_COVER_LETTER.header.name,
      DEMO_COVER_LETTER.date!,
      DEMO_COVER_LETTER.recipient!.company!,
      DEMO_COVER_LETTER.greeting,
      ...DEMO_COVER_LETTER.paragraphs.map((p) => p.text),
      DEMO_COVER_LETTER.closing,
    ];
    let at = -1;
    for (const part of order) {
      const next = text.indexOf(part);
      expect(next, `missing or out of order: ${part}`).toBeGreaterThan(at);
      at = next;
    }
  });

  it("signs with the header name unless a signature is given", () => {
    const { rerender } = render(<CoverLetterClassic />);
    expect(screen.getAllByText(DEMO_COVER_LETTER.header.name).length).toBe(2);
    rerender(<CoverLetterClassic doc={{ ...DEMO_COVER_LETTER, signature: "A. Rivera" }} />);
    expect(screen.getByText("A. Rivera")).toBeTruthy();
  });

  it("omits a recipient block it has nothing for, and carries each paragraph's sources", () => {
    const doc: CoverLetterDoc = {
      schema: "cover-letter@1",
      header: { name: "Sam Park" },
      greeting: "Hello,",
      paragraphs: [{ text: "I built the thing you need.", sources: ["acme-ship"] }],
      closing: "Best,",
    };
    const { container } = render(<CoverLetterClassic doc={doc} page="a4" />);
    expect(container.querySelector("address")).toBeNull();
    expect(container.querySelector(".para")?.getAttribute("data-sources")).toBe("acme-ship");
    expect(container.querySelector("style")?.textContent).toContain("size: A4");
  });
});
